{
  "primary_meaning": "A person of moral and spiritual deficiency who rejects divine wisdom, instruction, or God Himself (practical ungodliness or denial of God), rather than mere intellectual incapacity",
  "primary_basis": [
    "Psalm 14:1 / 53:1",
    "Proverbs 1:7",
    "Proverbs 10:23 / 12:15 / 14:9",
    "Proverbs 28:26",
    "Luke 12:16-21 (rich fool)",
    "Matthew 7:26 / 25:1-13 (foolish builder / virgins)"
  ],
  "alternatives": [
    {
      "meaning": "One who willingly becomes a 'fool for Christ,' embracing the apparent foolishness of the gospel and appearing foolish to worldly standards",
      "basis": [
        "1 Corinthians 1:18-25",
        "1 Corinthians 3:18",
        "1 Corinthians 4:10"
      ],
      "prominence": "common"
    },
    {
      "meaning": "A simple, naive, or inexperienced person (often distinguished from the hardened or scoffing fool) who may still be open to correction",
      "basis": [
        "Proverbs 1:4 / 7:7 / 14:15 / 22:3 (wisdom literature distinctions among 'simple,' 'fool,' 'scoffer')"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Someone who trusts in material wealth, self-sufficiency, or earthly security while neglecting spiritual realities",
      "basis": [
        "Luke 12:16-21"
      ],
      "prominence": "common"
    },
    {
      "meaning": "A term of contemptuous insult whose use against a brother is forbidden as a serious offense",
      "basis": [
        "Matthew 5:22"
      ],
      "prominence": "minority"
    },
    {
      "meaning": "The 'holy fool' (yurodivy) figure who feigns madness or unconventional behavior as a form of prophetic witness or humility",
      "basis": [
        "Later Eastern Orthodox tradition drawing loosely on Pauline language"
      ],
      "prominence": "rare"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "Across Hebrew (nabal, kesil, ewil) and Greek (moros, aphron) terms and traditional Christian exegesis, 'fool' primarily signals ethical-religious failure and rejection of God/wisdom rather than low IQ. Nuances exist by specific word and context, but the moral-spiritual sense is the clear consensus in biblical studies and Christian teaching."
}
